CREATE TABLE lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), class_id uuid NOT NULL REFERENCES class_groups(id), module_id uuid REFERENCES course_modules(id), teacher_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, description text NOT NULL DEFAULT '', scheduled_start timestamptz NOT NULL, scheduled_end timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('draft','scheduled','live','completed','cancelled')), live_session_id uuid, recording_status text NOT NULL DEFAULT 'hidden', recording_storage_key text, materials_published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(scheduled_end>scheduled_start));
CREATE INDEX lessons_schedule_idx ON lessons(school_id,scheduled_start,status);
CREATE INDEX lessons_class_idx ON lessons(class_id,status);
CREATE TABLE lesson_materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL REFERENCES lessons(id), title text NOT NULL, description text NOT NULL DEFAULT '', type text NOT NULL CHECK(type IN ('pdf','document','image','audio','video','link','other')), storage_key text, url text, client_file_name text, mime_type text, size bigint CHECK(size>=0), created_at timestamptz NOT NULL DEFAULT now(), CHECK((storage_key IS NOT NULL) <> (url IS NOT NULL)));
CREATE TABLE live_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL UNIQUE REFERENCES lessons(id), provider text NOT NULL, provider_session_id text NOT NULL, started_at timestamptz, ended_at timestamptz, recording_started_at timestamptz, recording_ended_at timestamptz, status text NOT NULL CHECK(status IN ('created','live','ended','failed')));
ALTER TABLE lessons ADD CONSTRAINT lessons_live_session_fk FOREIGN KEY(live_session_id) REFERENCES live_sessions(id);
CREATE TABLE lesson_recordings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL REFERENCES lessons(id), storage_key text NOT NULL, duration_seconds integer NOT NULL DEFAULT 0, size bigint NOT NULL DEFAULT 0, status text NOT NULL CHECK(status IN ('processing','available','failed','hidden')), created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE TABLE attendance_policies (school_id uuid PRIMARY KEY REFERENCES schools(id), minimum_live_attendance_basis_points integer NOT NULL CHECK(minimum_live_attendance_basis_points BETWEEN 0 AND 10000), updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid REFERENCES users(id));
CREATE TABLE attendance_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), lesson_id uuid NOT NULL REFERENCES lessons(id), student_id uuid NOT NULL REFERENCES users(id), joined_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, left_at timestamptz, total_present_seconds integer NOT NULL DEFAULT 0, lesson_duration_seconds integer NOT NULL DEFAULT 0, attendance_basis_points integer NOT NULL DEFAULT 0 CHECK(attendance_basis_points BETWEEN 0 AND 10000), status text NOT NULL CHECK(status IN ('present','partial','absent')), UNIQUE(lesson_id,student_id));
CREATE INDEX attendance_student_lesson_idx ON attendance_sessions(student_id,lesson_id);
CREATE TABLE attendance_presence_segments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attendance_session_id uuid NOT NULL REFERENCES attendance_sessions(id), joined_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, left_at timestamptz, present_seconds integer NOT NULL DEFAULT 0);
CREATE TABLE recording_views (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_id uuid NOT NULL REFERENCES users(id), lesson_id uuid NOT NULL REFERENCES lessons(id), first_viewed_at timestamptz NOT NULL, last_viewed_at timestamptz NOT NULL, watched_seconds integer NOT NULL DEFAULT 0, completed_basis_points integer NOT NULL DEFAULT 0 CHECK(completed_basis_points BETWEEN 0 AND 10000), UNIQUE(student_id,lesson_id));
CREATE TABLE language_skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), code text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(school_id,code));
CREATE TABLE grading_criteria (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), name text NOT NULL, description text NOT NULL DEFAULT '', max_score_scaled integer NOT NULL, display_order integer NOT NULL, active boolean NOT NULL DEFAULT true);

CREATE TABLE exercises (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), class_id uuid NOT NULL REFERENCES class_groups(id), lesson_id uuid REFERENCES lessons(id), module_id uuid REFERENCES course_modules(id), teacher_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, description text NOT NULL DEFAULT '', available_from timestamptz, due_at timestamptz, max_score_scaled integer NOT NULL CHECK(max_score_scaled>0), attempt_limit integer CHECK(attempt_limit>0), status text NOT NULL CHECK(status IN ('draft','published','closed','archived')), archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX exercises_deadline_idx ON exercises(school_id,due_at,status);
CREATE TABLE exercise_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exercise_id uuid NOT NULL REFERENCES exercises(id), type text NOT NULL CHECK(type IN ('multiple_choice','true_false','short_text','long_text','fill_blank','listening','speaking','matching')), prompt text NOT NULL, display_order integer NOT NULL, max_score_scaled integer NOT NULL CHECK(max_score_scaled>=0), required boolean NOT NULL DEFAULT true, configuration jsonb NOT NULL DEFAULT '{}');
CREATE TABLE exercise_question_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES exercise_questions(id), label text NOT NULL, value text NOT NULL, display_order integer NOT NULL, correct boolean NOT NULL DEFAULT false);
CREATE TABLE exercise_question_skills (question_id uuid NOT NULL REFERENCES exercise_questions(id), skill_id uuid NOT NULL REFERENCES language_skills(id), PRIMARY KEY(question_id,skill_id));
CREATE TABLE exercise_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exercise_id uuid NOT NULL REFERENCES exercises(id), student_id uuid NOT NULL REFERENCES users(id), started_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, status text NOT NULL CHECK(status IN ('in_progress','submitted','awaiting_review','graded')), objective_score_scaled integer, manual_score_scaled integer, final_score_scaled integer);
CREATE INDEX exercise_attempts_review_idx ON exercise_attempts(exercise_id,status);
CREATE TABLE exercise_answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES exercise_attempts(id), question_id uuid NOT NULL REFERENCES exercise_questions(id), text_answer text, selected_option_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(attempt_id,question_id));
CREATE TABLE audio_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES exercise_attempts(id), question_id uuid NOT NULL REFERENCES exercise_questions(id), storage_key text NOT NULL, duration_seconds integer NOT NULL, mime_type text NOT NULL, size bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(attempt_id,question_id));
CREATE TABLE exercise_grades (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL UNIQUE REFERENCES exercise_attempts(id), teacher_id uuid NOT NULL REFERENCES users(id), score_scaled integer NOT NULL, feedback text NOT NULL DEFAULT '', status text NOT NULL CHECK(status IN ('draft','published')), graded_at timestamptz, published_at timestamptz);

CREATE TABLE exams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), class_id uuid NOT NULL REFERENCES class_groups(id), module_id uuid REFERENCES course_modules(id), teacher_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, description text NOT NULL DEFAULT '', opens_at timestamptz, closes_at timestamptz, duration_minutes integer NOT NULL CHECK(duration_minutes>0), max_score_scaled integer NOT NULL CHECK(max_score_scaled>0), attempt_limit integer NOT NULL CHECK(attempt_limit>0), shuffle_questions boolean NOT NULL DEFAULT false, shuffle_options boolean NOT NULL DEFAULT false, show_result_immediately boolean NOT NULL DEFAULT false, show_correct_answers boolean NOT NULL DEFAULT false, status text NOT NULL CHECK(status IN ('draft','scheduled','open','closed','grading','published','archived')), archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX exams_window_idx ON exams(school_id,opens_at,closes_at,status);
CREATE TABLE exam_sections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL REFERENCES exams(id), title text NOT NULL, description text NOT NULL DEFAULT '', display_order integer NOT NULL, max_score_scaled integer NOT NULL);
CREATE TABLE exam_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL REFERENCES exams(id), section_id uuid NOT NULL REFERENCES exam_sections(id), type text NOT NULL CHECK(type IN ('multiple_choice','true_false','short_text','long_text','listening','speaking')), prompt text NOT NULL, display_order integer NOT NULL, max_score_scaled integer NOT NULL, required boolean NOT NULL DEFAULT true, configuration jsonb NOT NULL DEFAULT '{}');
CREATE TABLE exam_question_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES exam_questions(id), label text NOT NULL, value text NOT NULL, display_order integer NOT NULL, correct boolean NOT NULL DEFAULT false);
CREATE TABLE exam_question_skills (question_id uuid NOT NULL REFERENCES exam_questions(id), skill_id uuid NOT NULL REFERENCES language_skills(id), PRIMARY KEY(question_id,skill_id));
CREATE TABLE exam_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL REFERENCES exams(id), student_id uuid NOT NULL REFERENCES users(id), started_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, submitted_at timestamptz, status text NOT NULL CHECK(status IN ('in_progress','submitted','expired','awaiting_review','graded','published')), objective_score_scaled integer, manual_score_scaled integer, final_score_scaled integer);
CREATE INDEX exam_attempts_review_idx ON exam_attempts(exam_id,status,expires_at);
CREATE TABLE exam_answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES exam_attempts(id), question_id uuid NOT NULL REFERENCES exam_questions(id), text_answer text, selected_option_ids uuid[] NOT NULL DEFAULT '{}', saved_at timestamptz NOT NULL DEFAULT now(), UNIQUE(attempt_id,question_id));
CREATE TABLE exam_grades (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL UNIQUE REFERENCES exam_attempts(id), teacher_id uuid NOT NULL REFERENCES users(id), objective_score_scaled integer NOT NULL, manual_score_scaled integer NOT NULL, final_score_scaled integer NOT NULL, feedback text NOT NULL DEFAULT '', graded_at timestamptz, published_at timestamptz, status text NOT NULL CHECK(status IN ('draft','published')));
CREATE TABLE criterion_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), criterion_id uuid NOT NULL REFERENCES grading_criteria(id), grade_type text NOT NULL CHECK(grade_type IN ('exercise','exam')), grade_id uuid NOT NULL, score_scaled integer NOT NULL, feedback text NOT NULL DEFAULT '');
CREATE TABLE grade_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools(id), grade_type text NOT NULL CHECK(grade_type IN ('exercise','exam')), grade_id uuid NOT NULL, previous_score_scaled integer NOT NULL, new_score_scaled integer NOT NULL, reason text NOT NULL CHECK(length(reason)>=5), changed_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX grade_revisions_grade_idx ON grade_revisions(grade_type,grade_id,created_at);
